import { test, expect } from '@playwright/test';

test.describe('Mobile Landscape Orientation - Responsive Layout', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/');
  });

  test('should display app correctly in landscape orientation on mobile', async ({ page }) => {
    await page.setViewportSize({ width: 768, height: 444 });
    await page.setMobileDevice('iPhone 12');
    await page.setViewportSize({ width: 720, height: 400 });

    const appContainer = page.getByRole('main');
    await expect(appContainer).toBeVisible();

    const header = page.getByRole('banner');
    await expect(header).toBeVisible();

    const navLinks = page.getByRole('navigation').getByRole('link');
    await expect(navLinks).toBeVisible();

    const mainContent = page.getByRole('main');
    await expect(mainContent).toBeVisible();

    const footer = page.getByRole('contentinfo');
    await expect(footer).toBeVisible();

    const logo = page.getByRole('img', { name: /app logo/i });
    await expect(logo).toBeVisible();

    const mainTitle = page.getByRole('heading', { name: /welcome/i });
    await expect(mainTitle).toBeVisible();
  });

  test('should handle landscape orientation with correct content flow and no overflow', async ({ page }) => {
    await page.setViewportSize({ width: 720, height: 300 });
    await page.setMobileDevice('iPhone 12');

    const appContainer = page.getByRole('main');
    await expect(appContainer).toBeVisible();

    const header = page.getByRole('banner');
    await expect(header).toBeVisible();

    const navLinks = page.getByRole('navigation').getByRole('link');
    await expect(navLinks).toBeVisible();

    const mainContent = page.getByRole('main');
    await expect(mainContent).toBeVisible();

    const footer = page.getByRole('contentinfo');
    await expect(footer).toBeVisible();

    const overflow = page.locator('[data-testid="overflow-error"]');
    await expect(overflow).not.toBeVisible();

    const contentArea = page.locator('[data-testid="content-area"]');
    await expect(contentArea).toHaveCSS('overflow-y', 'visible');
  });
});
